                                  "required": ["build_id"]}}]


def fetch_log(build_id):
    return _LOG


HANDLERS = {"read_build_log": lambda build_id: fetch_log(build_id)}
_ANSWER = "Build 812 failed because test_total compares floats for money."


def _text(text):
