    return NS(content=[_text(_ANSWER)], stop_reason="end_turn")


class _Runner:
    def __init__(self, tools):
        self._tools = tools

    def until_done(self):
        self._tools[0](812)
        return NS(content=[_text(_ANSWER)], stop_reason="end_turn")


def _tool_runner(*, model, max_tokens, tools, messages, max_iterations=None, **kw):
    return _Runner(tools)


